 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find monochrome separator rows/columns, excluding the background.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    if row_seps:
        # Repeated horizontal bands: union the markings at each within-band location.
        starts = [0] + [r + 1 for r in row_seps]
        ends = row_seps + [h]
        sizes = [b-a for a,b in zip(starts, ends)]
        size = max(sizes)
        template = [[bg for _ in range(w)] for _ in range(size)]
        for a,b in zip(starts, ends):
            for y in range(b-a):
                for x in range(w):
                    if grid[a+y][x] != bg:
                        template[y][x] = grid[a+y][x]
        out = [row[:] for row in grid]
        for a,b in zip(starts, ends):
            for y in range(b-a):
                for x in range(w):
                    out[a+y][x] = template[y][x]
        return out

    if col_seps:
        starts = [0] + [c + 1 for c in col_seps]
        ends = col_seps + [w]
        sizes = [b-a for a,b in zip(starts, ends)]
        size = max(sizes)
        template = [[bg for _ in range(size)] for _ in range(h)]
        for a,b in zip(starts, ends):
            for x in range(b-a):
                for y in range(h):
                    if grid[y][a+x] != bg:
                        template[y][x] = grid[y][a+x]
        out = [row[:] for row in grid]
        for a,b in zip(starts, ends):
            for x in range(b-a):
                for y in range(h):
                    out[y][a+x] = template[y][x]
        return out
    return [row[:] for row in grid]
